    + "export let get(values: Array(a), index: Int): Option(a) =\n"
    + "    if index < 1 or index > length(values) then\n"
    + "        None\n"
    + "    else\n"
    + "        Some(values[index])\n"
    + "\n"
    + "// FFI Part 2 section 9's conversion, and **not** a door row — which is the\n"
