    + "    if exponent < 0 then\n"
    + "        throw(NegativeExponentFault(\"an integer exponent cannot be negative\"))\n"
    + "    else\n"
    + "        nativePow(value, exponent)\n"
    + "\n"
    + "honor Pow<BigInt> =\n"
    + "    pow = widened\n"
    + "\n"
    + "honor Hash<BigInt> =\n"
