    + "        if right == 0 then\n"
    + "            throw(DivideByZeroFault(\"BigInt.div: divisor is zero\"))\n"
    + "        else\n"
    + "            (left - left.mod(right)).quot(right)\n"
    + "\n"
    + "    (** The largest integer that divides both `left` and `right` with nothing\n"
    + "        left over, never negative:\\\n"
    + "        `(-4n).gcd(6n)` is `2n`.\\\n"
    + "        When one of them is zero the result is the other without its sign, so\n"
    + "        two zeros give zero. *)\n"
    + "    gcd(left, right) =\n"
    + "        var larger = left.abs()\n"
    + "        var smaller = right.abs()\n"
    + "        // Both operands are non-negative from here, so the loop's `rem` never\n"
    + "        // sees a zero divisor: a zero `smaller` is the exit condition.\n"
    + "        while smaller != 0\n"
    + "            let next = larger.rem(smaller)\n"
    + "            larger := smaller\n"
    + "            smaller := next\n"
    + "        larger\n"
    + "\n"
    + "// `bitwise.md` §4.4: BigInt's native operators already compute the true\n"
    + "// integer answer, so every member lowers to one of them.\n"
