    + "\n"
    + "(** An exact fraction, such as two thirds, kept as two integers: a top and a\n"
    + "    bottom. Where a `Float` rounds a third to `0.3333333333333333`, a `Rat`\n"
    + "    holds it exactly. A fraction is always kept in its simplest form with a\n"
    + "    positive bottom, so six over four is kept as three over two, and a negative\n"
    + "    fraction has its sign on the top. *)\n"
    + "opaque record Rat derives (Eq, Hash) = {\n"
    + "    top: BigInt,\n"
    + "    bottom: BigInt,\n"
    + "}\n"
    + "\n"
    + "// `DivideByZeroFault` is `Integral.hex`'s, in scope through the prelude: one\n"
    + "// declaration for every type whose division is partial, rather than one per\n"
    + "// honoring module (#344).\n"
    + "\n"
    + "(** The fraction `top` over `bottom`, in its simplest form:\\\n"
    + "    `Rat.create(6, 4)` is three over two, and shows as `\"3/2\"`.\\\n"
    + "    A negative `bottom` moves its sign to the top. Throws `DivideByZeroFault`\n"
    + "    when `bottom` is zero. *)\n"
    + "export let create(top: BigInt, bottom: BigInt): Rat =\n"
    + "    if bottom == 0 then\n"
    + "        throw(DivideByZeroFault(\"Rat.create: bottom is zero\"))\n"
