    + "            Rat({top = -reducedTop, bottom = -reducedBottom})\n"
    + "        else\n"
    + "            Rat({top = reducedTop, bottom = reducedBottom})\n"
    + "\n"
    + "(** The top of the fraction in its simplest form. The top carries the sign:\\\n"
    + "    `Rat.create(6, -4).top()` is `-3n`. *)\n"
    + "export let top(value: Rat): BigInt = value.top\n"
