    + "// The escape whose backslash is at `position`, and the position after it.\n"
    + "let readEscape(pattern: String, text: Vector(String), position: Int): Outcome((Escaped, Int), Refusal) =\n"
    + "    let size = Vector.length(text)\n"
    + "    if position + 1 > size then\n"
