    + "// `ranges` with `[low, high]` added, kept sorted, disjoint and merged.\n"
    + "let addRange(ranges: Vector((Int, Int)), low: Int, high: Int): Vector((Int, Int)) =\n"
    + "    var result: Vector((Int, Int)) = []\n"
    + "    var pendingLow = low\n"
    + "    var pendingHigh = high\n"
