    + "\n"
    + "// ---------------------------------------------------------------------------\n"
    + "// Repetition (§2.5)\n"
    + "\n"
    + "let readDigits(text: Vector(String), position: Int): (Int, Int, Int) =\n"
    + "    let size = Vector.length(text)\n"
    + "    var at = position\n"
    + "    var value = 0\n"
