    + "    var closed = False\n"
    + "    var reading = True\n"
    + "    while reading\n"
    + "        if at > size then\n"
    + "            failure := Some(fault(\"missing `)` for the group opened here; close it, or write `\\\\(` for a literal\", opening))\n"
