    + "        if takeLeft then leftAt := leftAt + 1 else rightAt := rightAt + 1\n"
    + "        let count = Vector.length(result)\n"
    + "        if count > 0 and low <= result[count].item2 + 1 then\n"
    + "            if high > result[count].item2 then result := Vector.set(result, count, (result[count].item1, high))\n"
