    + "\n"
    + "// Every codepoint not in `set`, over U+0000–U+10FFFF.\n"
    + "let complementOf(set: Vector((Int, Int))): Vector((Int, Int)) =\n"
    + "    var result: Vector((Int, Int)) = []\n"
    + "    var next = 0\n"
    + "    for (low, high) in set\n"
    + "        if low > next then result := result.append((next, low - 1))\n"
    + "        next := high + 1\n"
    + "    if next <= lastPoint then result.append((next, lastPoint)) else result\n"
    + "\n"
    + "// Whether `point` is in `set`, by binary search.\n"
    + "let contains(set: Vector((Int, Int)), point: Int): Bool =\n"
    + "    var low = 1\n"
    + "    var high = Vector.length(set)\n"
    + "    var found = False\n"
    + "    while not found and low <= high\n"
    + "        let middle = Int.div(low + high, 2)\n"
    + "        let (from, to) = set[middle]\n"
    + "        if point < from then\n"
    + "            high := middle - 1\n"
    + "        else if point > to then\n"
    + "            low := middle + 1\n"
    + "        else\n"
    + "            found := True\n"
    + "    found\n"
    + "\n"
    + "// `points` in ascending order, by merge sort.\n"
    + "fun sortedPoints(points: Vector(Int)): Vector(Int) =\n"
    + "    let count = Vector.length(points)\n"
    + "    if count <= 1 then\n"
    + "        points\n"
    + "    else\n"
    + "        let half = Int.div(count, 2)\n"
    + "        let left = sortedPoints(points[1..half])\n"
    + "        let right = sortedPoints(points[half + 1..count])\n"
    + "        var merged: Vector(Int) = []\n"
    + "        var leftAt = 1\n"
    + "        var rightAt = 1\n"
    + "        while leftAt <= half or rightAt <= count - half\n"
    + "            if rightAt > count - half or (leftAt <= half and left[leftAt] <= right[rightAt]) then\n"
    + "                merged := merged.append(left[leftAt])\n"
    + "                leftAt := leftAt + 1\n"
    + "            else\n"
    + "                merged := merged.append(right[rightAt])\n"
    + "                rightAt := rightAt + 1\n"
    + "        merged\n"
    + "\n"
    + "// `points`, in any order, as a set.\n"
    + "let setOfPoints(points: Vector(Int)): Vector((Int, Int)) =\n"
    + "    var result: Vector((Int, Int)) = []\n"
    + "    for point in sortedPoints(points)\n"
    + "        let count = Vector.length(result)\n"
    + "        if count > 0 and point <= result[count].item2 + 1 then\n"
    + "            if point > result[count].item2 then result := Vector.set(result, count, (result[count].item1, point))\n"
    + "        else\n"
    + "            result := result.append((point, point))\n"
