    + "\n"
    + "// `set` closed under simple case folding (§3.4): every codepoint whose folding\n"
    + "// equals a member's. The points a member's orbit adds are few beside the set,\n"
    + "// so they are gathered first and merged once.\n"
    + "let foldedSet(set: Vector((Int, Int))): Vector((Int, Int)) =\n"
    + "    var added: Vector(Int) = []\n"
    + "    for (low, high) in set\n"
    + "        var point = low\n"
    + "        while point <= high\n"
