    + "            point := point + 1\n"
    + "    unionOf(set, setOfPoints(added))\n"
    + "\n"
    + "// The codepoints one class item stands for.\n"
    + "let itemSet(item: Syntax.ClassItem): Vector((Int, Int)) = match item\n"
    + "    Syntax.Range(low, high) => [(low, high)]\n"
    + "    Syntax.Property(kind, value, negated) =>\n"
