    + "\n"
    + "// A class's codepoints, in §6.1's order: each item resolved and complemented\n"
    + "// where it is negated, the union taken, folded where the class is folded, and\n"
    + "// complemented where the class is negated. Fold before complement is what makes\n"
    + "// `(?i)[^a]` not match `A`.\n"
    + "let classSet(items: Vector(Syntax.ClassItem), negated: Bool, folded: Bool): Vector((Int, Int)) =\n"
    + "    var set: Vector((Int, Int)) = []\n"
    + "    for item in items\n"
    + "        set := unionOf(set, itemSet(item))\n"
    + "    let closed = if folded then foldedSet(set) else set\n"
    + "    if negated then complementOf(closed) else closed\n"
    + "\n"
    + "// ---------------------------------------------------------------------------\n"
    + "// The NFA (§6.1)\n"
    + "//\n"
    + "// One Thompson construction over the tree. An instruction is an operation and\n"
    + "// two operands, at a zero-based program counter:\n"
    + "//\n"
    + "//  - `consume c`: one codepoint in class `c`, then the next instruction;\n"
    + "//  - `split x y`: both, `x` first in priority (§3.2);\n"
    + "//  - `jump x`;\n"
    + "//  - `save s`: the position into capture slot `s` (group `g` is slots `2g`\n"
    + "//    and `2g + 1`);\n"
    + "//  - `assert a`: an assertion (`anchorCode`), consuming nothing;\n"
    + "//  - `match`.\n"
    + "//\n"
    + "// The construction is pure: it builds vectors, which `compile` then freezes\n"
    + "// into buffers.\n"
    + "\n"
    + "let opMatch: Int = 0\n"
    + "let opConsume: Int = 1\n"
    + "let opSplit: Int = 2\n"
    + "let opJump: Int = 3\n"
    + "let opSave: Int = 4\n"
    + "let opAssert: Int = 5\n"
    + "\n"
    + "record ClassSpec = { items: Vector(Syntax.ClassItem), negated: Bool, folded: Bool }\n"
    + "\n"
    + "record Code = {\n"
    + "    ops: Vector(Int),\n"
    + "    first: Vector(Int),\n"
    + "    second: Vector(Int),\n"
    + "    classes: Vector(ClassSpec),\n"
    + "}\n"
    + "\n"
    + "let anchorCode(kind: Syntax.AnchorKind): Int = match kind\n"
    + "    Syntax.TextStart => 0\n"
    + "    Syntax.TextEnd => 1\n"
    + "    Syntax.LineStart => 2\n"
    + "    Syntax.LineEnd => 3\n"
    + "    Syntax.WordBoundary => 4\n"
    + "    Syntax.NotWordBoundary => 5\n"
    + "\n"
    + "let counter(code: Code): Int = Vector.length(code.ops)\n"
    + "\n"
    + "let emit(code: Code, op: Int, first: Int, second: Int): Code =\n"
    + "    { code with ops = code.ops.append(op), first = code.first.append(first), second = code.second.append(second) }\n"
    + "\n"
    + "let setFirst(code: Code, at: Int, target: Int): Code = { code with first = Vector.set(code.first, at + 1, target) }\n"
    + "\n"
    + "let setSecond(code: Code, at: Int, target: Int): Code = { code with second = Vector.set(code.second, at + 1, target) }\n"
    + "\n"
    + "let kindCode(kind: Syntax.PropertyKind): Int = match kind\n"
    + "    Syntax.GeneralCategory => 0\n"
    + "    Syntax.Script => 1\n"
    + "    Syntax.ScriptExtensions => 2\n"
    + "    Syntax.Binary => 3\n"
    + "    Syntax.Any => 4\n"
    + "    Syntax.Ascii => 5\n"
    + "    Syntax.Assigned => 6\n"
    + "    Syntax.Word => 7\n"
    + "\n"
    + "let sameItem(left: Syntax.ClassItem, right: Syntax.ClassItem): Bool = match (left, right)\n"
    + "    (Syntax.Range(leftLow, leftHigh), Syntax.Range(rightLow, rightHigh)) => leftLow == rightLow and leftHigh == rightHigh\n"
    + "    (Syntax.Property(leftKind, leftValue, leftNegated), Syntax.Property(rightKind, rightValue, rightNegated)) =>\n"
    + "        kindCode(leftKind) == kindCode(rightKind) and leftValue == rightValue and leftNegated == rightNegated\n"
    + "    _ => False\n"
    + "\n"
    + "let sameSpec(left: ClassSpec, right: ClassSpec): Bool =\n"
    + "    var same = left.negated == right.negated and left.folded == right.folded and\n"
    + "        Vector.length(left.items) == Vector.length(right.items)\n"
    + "    var index = 1\n"
    + "    while same and index <= Vector.length(left.items)\n"
    + "        same := sameItem(left.items[index], right.items[index])\n"
    + "        index := index + 1\n"
    + "    same\n"
    + "\n"
    + "// A `consume` of `spec`'s class. A class the program already holds is reused,\n"
    + "// so that a counted repetition's copies, and every repeated literal, resolve\n"
    + "// once (§6.4: a folded `\\p{L}` costs its membership once).\n"
    + "let emitClass(code: Code, spec: ClassSpec): Code =\n"
    + "    var found = -1\n"
    + "    var index = 1\n"
    + "    while found < 0 and index <= Vector.length(code.classes)\n"
