    + "        index := index + 1\n"
    + "    if found >= 0 then\n"
    + "        emit(code, opConsume, found, 0)\n"
    + "    else\n"
    + "        emit({ code with classes = code.classes.append(spec) }, opConsume, Vector.length(code.classes), 0)\n"
    + "\n"
    + "let singleClass(point: Int): ClassSpec = ClassSpec({ items = [Syntax.Range(point, point)], negated = False, folded = False })\n"
    + "\n"
    + "// A `split` at `at` whose preferred branch is the next instruction and whose\n"
    + "// other is `out` — or the other way round where the repetition is lazy.\n"
    + "let setSplit(code: Code, at: Int, out: Int, greedy: Bool): Code =\n"
    + "    if greedy then setSecond(setFirst(code, at, at + 1), at, out) else setSecond(setFirst(code, at, out), at, at + 1)\n"
    + "\n"
    + "// Whether `expr` can match the empty string.\n"
    + "fun nullable(expr: Syntax.Expr): Bool = match expr\n"
    + "    Syntax.Empty => True\n"
    + "    Syntax.Literal(_) => False\n"
    + "    Syntax.Dot(_) => False\n"
    + "    Syntax.Class(_, _, _) => False\n"
    + "    Syntax.Anchor(_) => True\n"
    + "    Syntax.Concat(parts) =>\n"
    + "        var all = True\n"
    + "        for part in parts\n"
    + "            all := all and nullable(part)\n"
    + "        all\n"
    + "    Syntax.Alternate(branches) =>\n"
    + "        var any = False\n"
    + "        for branch in branches\n"
    + "            any := any or nullable(branch)\n"
    + "        any\n"
