    + "    Syntax.Capture(body, _, _) => nullable(body)\n"
    + "\n"
    + "// `expr`'s instructions after `code`'s. `backward` builds the program for the\n"
    + "// reverse scan (§6.2): a sequence's parts in reverse order and no capture\n"
    + "// slots, since that scan locates a match's start and assigns no captures.\n"
    + "fun emitExpr(code: Code, expr: Syntax.Expr, backward: Bool): Code = match expr\n"
    + "    Syntax.Empty => code\n"
