    + "            emitClass(code, ClassSpec({ items = [Syntax.Range(10, 10)], negated = True, folded = False }))\n"
    + "    Syntax.Class(items, negated, folded) =>\n"
    + "        emitClass(code, ClassSpec({ items = items, negated = negated, folded = folded }))\n"
