    + "        // in a jump past the rest.\n"
    + "        var current = code\n"
    + "        var jumps: Vector(Int) = []\n"
    + "        let count = Vector.length(branches)\n"
    + "        var index = 1\n"
    + "        while index < count\n"
    + "            let split = counter(current)\n"
    + "            current := emitExpr(emit(current, opSplit, split + 1, 0), branches[index], backward)\n"
    + "            jumps := jumps.append(counter(current))\n"
