    + "            current := setFirst(current, jump, end)\n"
    + "        current\n"
    + "    Syntax.Repeat(body, min, max, greedy) =>\n"
    + "        var current = code\n"
    + "        var copies = 0\n"
    + "        while copies < min\n"
