    + "            copies := copies + 1\n"
    + "        match max\n"
    + "            None =>\n"
    + "                if nullable(body) then\n"
    + "                    // `x*` over a body that can match empty is `(?:x+)?`, as\n"
    + "                    // RE2 and Go compile it (Go issue 46123): one optional\n"
    + "                    // entry, then a loop back that the body must reach. Read\n"
    + "                    // as a plain loop, the program-counter dedupe would end\n"
    + "                    // every path through an empty iteration, and `(|a)*` on\n"
    + "                    // `aa` would match `aa` where `(?:|a){0,5}` matches the\n"
    + "                    // empty string (§3.2).\n"
    + "                    let entry = counter(current)\n"
    + "                    let start = entry + 1\n"
    + "                    current := emitExpr(emit(current, opSplit, 0, 0), body, backward)\n"
    + "                    let back = counter(current)\n"
    + "                    current := emit(current, opSplit, 0, 0)\n"
    + "                    let end = counter(current)\n"
    + "                    let looped = if greedy then setSecond(setFirst(current, back, start), back, end)\n"
    + "                        else setSecond(setFirst(current, back, end), back, start)\n"
