    + "                    // `x*` after the required copies: a split back over the body.\n"
    + "                    let loop = counter(current)\n"
    + "                    current := emitExpr(emit(current, opSplit, 0, 0), body, backward)\n"
    + "                    current := emit(current, opJump, loop, 0)\n"
    + "                    setSplit(current, loop, counter(current), greedy)\n"
