    + "            emit(opened, opSave, 2 * index + 1, 0)\n"
    + "\n"
    + "// The whole pattern's program: group 0 saved around the tree, then `match`.\n"
    + "let codeOf(pattern: Syntax.Pattern): Code =\n"
    + "    let empty = Code({ ops = [], first = [], second = [], classes = [] })\n"
    + "    let body = emitExpr(emit(empty, opSave, 0, 0), pattern.root, False)\n"
    + "    emit(emit(body, opSave, 1, 0), opMatch, 0, 0)\n"
    + "\n"
    + "// A new program after `code`'s, sharing its classes.\n"
    + "let after(code: Code): Code = { code with ops = [], first = [], second = [] }\n"
    + "\n"
    + "// The forward scan's program (§6.2): the pattern behind a lazy `(?s:.)*?`, so\n"
    + "// that every start is tried at the lowest priority and the first match found\n"
    + "// cuts the rest, as leftmost-first wants.\n"
    + "let forwardOf(code: Code, pattern: Syntax.Pattern): Code =\n"
    + "    let any = ClassSpec({ items = [Syntax.Range(0, lastPoint)], negated = False, folded = False })\n"
    + "    let seeded = emitClass(emit(after(code), opSplit, 3, 1), any)\n"
    + "    let looped = emit(seeded, opJump, 0, 0)\n"
    + "    emit(emitExpr(looped, pattern.root, False), opMatch, 0, 0)\n"
    + "\n"
    + "// The reverse scan's program: the pattern read backwards, anchored.\n"
    + "let backwardOf(code: Code, pattern: Syntax.Pattern): Code =\n"
    + "    emit(emitExpr(after(code), pattern.root, True), opMatch, 0, 0)\n"
    + "\n"
    + "// ---------------------------------------------------------------------------\n"
    + "// The compiled program (§6.1, §6.3)\n"
    + "//\n"
    + "// The program a `Regex` carries: the instructions, frozen into buffers that no\n"
    + "// row writes after `compile` returns, and the classes by their tree items, with\n"
    + "// the one memo resolution fills on first use (§6.2's second transparent memo).\n"
    + "record Compiled = {\n"
    + "    ops: Buffer(Int),\n"
    + "    first: Buffer(Int),\n"
    + "    second: Buffer(Int),\n"
    + "    size: Int,\n"
    + "    classes: Vector(ClassSpec),\n"
    + "    resolved: Buffer(Option(Vector((Int, Int)))),\n"
    + "    groupCount: Int,\n"
    + "    forward: Machine,\n"
    + "    backward: Machine,\n"
    + "    alphabet: Buffer(Option(Vector(Int))),\n"
    + "    caches: Buffer(Option(Dfa)),\n"
    + "    assertive: Bool,\n"
    + "    marks: Buffer(Buffer(Int)),\n"
    + "    stamps: Buffer(Int),\n"
    + "}\n"
    + "\n"
    + "// One program of instructions, frozen: the forward and reverse scans' own.\n"
    + "record Machine = { ops: Buffer(Int), first: Buffer(Int), second: Buffer(Int), size: Int }\n"
    + "\n"
    + "let frozen(values: Vector(Int)): Buffer(Int) =\n"
    + "    let buffer = create~(Vector.length(values), 0)\n"
    + "    var index = 0\n"
    + "    for value in values\n"
    + "        write~(buffer, index, value)\n"
    + "        index := index + 1\n"
    + "    buffer\n"
    + "\n"
    + "let machineOf(code: Code): Machine =\n"
    + "    Machine({ ops = frozen~(code.ops), first = frozen~(code.first), second = frozen~(code.second), size = Vector.length(code.ops) })\n"
    + "\n"
    + "// The program for `pattern`. It reads no table: class resolution waits for the\n"
    + "// program's first use (§6.1), so a program emitted as a constant carries its\n"
    + "// properties by name.\n"
    + "let compile(pattern: Syntax.Pattern): Compiled =\n"
    + "    let code = codeOf(pattern)\n"
    + "    let forward = forwardOf(code, pattern)\n"
    + "    let backward = backwardOf(forward, pattern)\n"
    + "    // The three programs' scratch marks, owned by the program and reused by\n"
    + "    // every search: a mark holds the stamp of the last use that reached it, and\n"
    + "    // stamps only grow (`stamps`), so no search reads another's marks as its own.\n"
    + "    let marks = create~(3, create~(0, 0))\n"
    + "    write~(marks, 0, create~(Vector.length(code.ops), -1))\n"
    + "    write~(marks, 1, create~(Vector.length(forward.ops), -1))\n"
    + "    write~(marks, 2, create~(Vector.length(backward.ops), -1))\n"
