    + "    for op in code.ops\n"
    + "        if op == opAssert then assertive := True\n"
    + "    Compiled({\n"
    + "        ops = frozen~(code.ops),\n"
    + "        first = frozen~(code.first),\n"
    + "        second = frozen~(code.second),\n"
    + "        size = Vector.length(code.ops),\n"
    + "        classes = backward.classes,\n"
    + "        resolved = create~(Vector.length(backward.classes), None),\n"
