    + "        forward = machineOf~(forward),\n"
    + "        backward = machineOf~(backward),\n"
    + "        alphabet = create~(1, None),\n"
    + "        caches = create~(2, None),\n"
    + "        assertive = assertive,\n"
    + "        marks = marks,\n"
    + "        stamps = create~(1, 0),\n"
    + "    })\n"
    + "\n"
    + "\n"
    + "// Class `index`'s codepoints, resolved once and kept in the program.\n"
    + "let classOf(program: Compiled, index: Int): Vector((Int, Int)) =\n"
    + "    match read~(program.resolved, index)\n"
    + "        Some(set) => set\n"
    + "        None =>\n"
    + "            let spec = program.classes[index + 1]\n"
    + "            let set = classSet(spec.items, spec.negated, spec.folded)\n"
    + "            write~(program.resolved, index, Some(set))\n"
    + "            set\n"
    + "\n"
    + "// ---------------------------------------------------------------------------\n"
    + "// The search: a Pike VM (§6.2)\n"
    + "//\n"
    + "// The NFA simulated over the subject one codepoint at a time, each thread\n"
    + "// carrying its own capture slots, the threads kept in priority order so that\n"
    + "// the first to reach `match` is the leftmost-first match (§3.2). Linear in the\n"
    + "// subject times the program, whatever the pattern. The lazy DFA of §6.2 runs in\n"
    + "// front of it in a later step and answers the same matches.\n"
    + "//\n"
    + "// A thread's slots hold, for each capture slot, the codepoint position and the\n"
    + "// code-unit offset it saved, both -1 until saved.\n"
    + "\n"
    + "record Thread = { pc: Int, slots: Vector(Int) }\n"
    + "\n"
    + "// Where the scan stands: the position and code-unit offset of the next\n"
    + "// codepoint, and the codepoints on either side, -1 at the text's edges.\n"
    + "record Place = { position: Int, offset: Int, before: Int, after: Int }\n"
    + "\n"
    + "let width(point: Int): Int = if point > 65_535 then 2 else 1\n"
    + "\n"
    + "let isWord(point: Int): Bool = point >= 0 and contains(propertyRanges(Syntax.Word, \"\"), point)\n"
    + "\n"
    + "let holds(kind: Int, place: Place): Bool =\n"
    + "    if kind == 0 then\n"
    + "        place.position == 1\n"
    + "    else if kind == 1 then\n"
