    + "    them in the opposite order, slice with a range that counts up and then call\n"
    + "    `reverse`. `start` and `end` are the two ends of the range that was\n"
    + "    given. *)\n"
    + "export fault SliceFault(start: Int, end: Int)\n"
    + "\n"
    + "// The whole boundary Collections Part 3 section 7 pins: representation-sensitive\n"
    + "// length and end updates, signed indexed access, persistent indexed update, and\n"
