    + "    export type vector as Vector(+a)\n"
    + "\n"
    + "    (** The number of elements. *)\n"
    + "    export fun vectorLength as length(values: Vector(a)) -> Int\n"
    + "\n"
    + "    (** A new vector with `value` added after the last element. *)\n"
    + "    export fun vectorAppend as append(values: Vector(a), value: a) -> Vector(a)\n"
    + "\n"
    + "    (** A new vector with `value` added before the first element. *)\n"
    + "    export fun vectorPrepend as prepend(values: Vector(a), value: a) -> Vector(a)\n"
    + "\n"
    + "    (** The element at the position `index`. A positive `index` counts from the\n"
    + "        start, so 1 is the first element. A negative `index` counts back from\n"
    + "        the end, so -1 is the last:\\\n"
